 const createAction=(o=selected)=>{setLoadedAction(undefined);setPalette([o]);setActionName(`New ${o.name} Action`);setPage('builder');notify(`${o.name} added to Action Builder`)}
 const saveAction=(saved:PersistedAction)=>{const value=toAction(saved,libraryObjects);setActions(old=>[value,...old.filter(x=>x.id!==value.id)]);setLoadedAction(value);setBuild('Needs Rebuild')}
 const openAction=(action:Action)=>{setLoadedAction(action);setActionName(action.name);setPalette(action.objects);setPage('builder')}
 const updateObject=(value:StudioObject)=>{setLibraryObjects(xs=>xs.map(x=>x.id===value.id?value:x));setSelected(value);setPalette(xs=>xs.map(x=>x.id===value.id?value:x));setActions(xs=>xs.map(a=>({...a,objects:a.objects.map(x=>x.id===value.id?value:x)})))}
